import torch

class M(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.a = torch.nn.Linear(64, 128)
        self.b = torch.nn.Linear(128, 64)
    def forward(self, x):
        return self.b(self.a(x).relu())

model_c = torch.compile(M())
x = torch.randn(32, 64, device="cuda", requires_grad=True)
y = model_c(x).sum()
y.backward()
